import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.util.*;import java.util.zip.*;import java.nio.file.*;
public class Patch implements Opcodes{
 static final String N="dev/zomboid/decor/needs/",MC="net/minecraft/";static int hooks;
 static byte[] bytes(ClassNode c){ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static void event(Map<String,byte[]> out,String name,boolean mod,boolean client,String[][] methods){ClassNode c=new ClassNode();c.version=V21;c.access=ACC_PUBLIC;c.name=N+name;c.superName="java/lang/Object";AnnotationNode a=new AnnotationNode("Lnet/neoforged/fml/common/EventBusSubscriber;");a.values=new ArrayList<>(List.of("modid","doomsday_decoration","bus",new String[]{"Lnet/neoforged/fml/common/EventBusSubscriber$Bus;",mod?"MOD":"GAME"}));if(client){a.values.add("value");a.values.add(Collections.singletonList(new String[]{"Lnet/neoforged/api/distmarker/Dist;","CLIENT"}));}c.visibleAnnotations=List.of(a);
  for(String[] v:methods){MethodNode m=new MethodNode(ACC_PUBLIC|ACC_STATIC,v[0],"(L"+v[1]+";)V",null,null);c.methods.add(m);AnnotationNode sub=new AnnotationNode("Lnet/neoforged/bus/api/SubscribeEvent;");sub.values=new ArrayList<>(List.of("priority",new String[]{"Lnet/neoforged/bus/api/EventPriority;","LOWEST"}));m.visibleAnnotations=List.of(sub);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new MethodInsnNode(INVOKESTATIC,N+v[2],v[3],"(Ljava/lang/Object;)V",false));m.instructions.add(new InsnNode(RETURN));}out.put(c.name+".class",bytes(c));
 }
 static byte[] patch(byte[] b){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);
 if(c.name.equals("net/mcreator/doomsdaydecoration/DoomsdayDecorationMod")){for(MethodNode m:c.methods)for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof LdcInsnNode l&&l.cst.equals("vendingmachine_4")){AbstractInsnNode next=i.getNext();if(!(next instanceof MethodInsnNode n)||!n.owner.equals("java/util/Set")||!n.name.equals("of"))throw new IllegalStateException("WC placement registration mismatch");m.instructions.insert(i,new LdcInsnNode("wc"));n.desc="(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)Ljava/util/Set;";hooks++;}return bytes(c);}
 if(!c.name.equals("net/mcreator/doomsdaydecoration/port/PortedBlock"))return b;
 for(MethodNode m:c.methods)if(m.name.equals("useWithoutItem")){InsnList x=new InsnList();for(int i=1;i<=4;i++)x.add(new VarInsnNode(ALOAD,i));x.add(new MethodInsnNode(INVOKESTATIC,N+"Toilets","use","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)Z",false));LabelNode next=new LabelNode();x.add(new JumpInsnNode(IFEQ,next));x.add(new FieldInsnNode(GETSTATIC,MC+"world/InteractionResult","SUCCESS","L"+MC+"world/InteractionResult;"));x.add(new InsnNode(ARETURN));x.add(next);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);hooks++;}
 String desc="(L"+MC+"world/level/block/state/BlockState;L"+MC+"world/level/Level;L"+MC+"core/BlockPos;L"+MC+"world/entity/Entity;)V";if(c.methods.stream().anyMatch(m->m.name.equals("entityInside")))throw new IllegalStateException("Existing entityInside");MethodNode m=new MethodNode(ACC_PUBLIC,"entityInside",desc,null,null);for(int i=1;i<=4;i++)m.instructions.add(new VarInsnNode(ALOAD,i));m.instructions.add(new MethodInsnNode(INVOKESTATIC,N+"Wire","touch","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false));for(int i=0;i<=4;i++)m.instructions.add(new VarInsnNode(ALOAD,i));m.instructions.add(new MethodInsnNode(INVOKESPECIAL,MC+"world/level/block/Block","entityInside",desc,false));m.instructions.add(new InsnNode(RETURN));c.methods.add(m);hooks++;return bytes(c);
 }
 static void verify(byte[] b)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}
 public static void main(String[]args)throws Exception{Map<String,byte[]> out=new TreeMap<>();try(ZipFile z=new ZipFile(args[0])){for(ZipEntry e:Collections.list(z.entries())){byte[] b=z.getInputStream(e).readAllBytes();out.put(e.getName(),e.getName().endsWith(".class")?patch(b):b);}}if(hooks!=3)throw new IllegalStateException("Expected3 hooks, got "+hooks);try(var stream=Files.walk(Path.of(args[2]))){for(Path p:stream.filter(p->p.toString().endsWith(".class")).toList())out.put(Path.of(args[2]).relativize(p).toString(),Files.readAllBytes(p));}
 event(out,"NeedsEvents",false,false,new String[][]{{"tick","net/neoforged/neoforge/event/tick/PlayerTickEvent$Post","Needs","tick"},{"commands","net/neoforged/neoforge/event/RegisterCommandsEvent","Needs","commands"}});
 event(out,"NeedsModEvents",true,false,new String[][]{{"content","net/neoforged/neoforge/registries/RegisterEvent","Content","register"},{"network","net/neoforged/neoforge/network/event/RegisterPayloadHandlersEvent","Network","register"}});
 event(out,"NeedsClientModEvents",true,true,new String[][]{{"keys","net/neoforged/neoforge/client/event/RegisterKeyMappingsEvent","client/NeedsClient","keys"}});
 event(out,"NeedsClientEvents",false,true,new String[][]{{"tick","net/neoforged/neoforge/client/event/ClientTickEvent$Post","client/NeedsClient","tick"},{"input","net/neoforged/neoforge/client/event/MovementInputUpdateEvent","client/NeedsClient","input"}});
 try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:out.entrySet()){if(e.getKey().endsWith(".class")&&(e.getKey().startsWith(N)||e.getKey().contains("PortedBlock.class")||e.getKey().endsWith("DoomsdayDecorationMod.class")))verify(e.getValue());ZipEntry entry=new ZipEntry(e.getKey());entry.setTime(0);z.putNextEntry(entry);z.write(e.getValue());z.closeEntry();}}System.out.println("Placement, toilet and wire hooks + sided event/network subscribers verified");
 }
}
